117	func TestParse_DuplicateRejectedRegardlessOfValues(t *testing.T) {
118		base := `"app":"a","revision":"r","image":"i","batchSize":1`
119		// Same value twice must still be rejected.
120		for _, val := range []string{`true`, `false`, `null`, `1`, `1.5`, `"str"`, `[1,2]`, `{"k":"v"}`} {
121			t.Run("same value "+val, func(t *testing.T) {
122				body := `{"id":"x","tags":{"env":` + val + `,"env":` + val + `}}`
123				err := parseDupErr(t, `{`+base+`,"clusters":[`+body+`]}`)
124				if !strings.Contains(err.Error(), "env") {
125					t.Fatalf("expected field name in %q", err)
126				}
127			})
128		}
129		// Different value types on either side must be rejected.
130		pairs := [][2]string{
131			{`1`, `true`},
132			{`"a"`, `null`},
133			{`[]`, `{}`},
134			{`false`, `"false"`},
135		}
136		for _, p := range pairs {
137			t.Run("mixed "+p[0]+" "+p[1], func(t *testing.T) {
138				body := `{"id":"x","tags":{"env":` + p[0] + `,"env":` + p[1] + `}}`
139				err := parseDupErr(t, `{`+base+`,"clusters":[`+body+`]}`)
140				if !strings.Contains(err.Error(), "env") {
141					t.Fatalf("expected field name in %q", err)
142				}
143			})
144		}
145	}
