168	func TestParse_DuplicateCheckIsPerObject(t *testing.T) {
169		base := `"app":"a","revision":"r","image":"i","batchSize":1`
170		// Two clusters may both have an "env" tag.
171		valid := `{` + base + `,"clusters":[` +
172			`{"id":"a","tags":{"env":"prod"}},` +
173			`{"id":"b","tags":{"env":"dev"}}]}`
174		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
175			t.Fatalf("two clusters sharing a tag key must be valid: %v", err)
176		}
177		// Two conditions may both contain "region".
178		valid = `{` + base + `,"clusters":[],` +
179			`"include":[{"region":"us"},{"region":"eu"}]}`
180		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
181			t.Fatalf("two conditions sharing a key must be valid: %v", err)
182		}
183		// Repeated identical conditions are not duplicates.
184		valid = `{` + base + `,"clusters":[],` +
185			`"include":[{"env":"prod"},{"env":"prod"}]}`
186		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
187			t.Fatalf("repeated identical conditions must be valid: %v", err)
188		}
189		// Same key in parent object and nested object is fine.
190		valid = `{` + base + `,"clusters":[],"meta":{"env":"x","nested":{"env":"y"}}}`
191		if _, err := ParseReleaseInput([]byte(valid)); err != nil {
192			t.Fatalf("same key in parent and nested object must be valid: %v", err)
193		}
194	}
