287	// runCLI invokes the darksafe command with the given arguments and returns
288	// exit code, stdout and stderr.
289	func runCLI(t *testing.T, args ...string) (int, string, string) {
290		t.Helper()
291		cmd := exec.Command("go", append([]string{"run", "./cmd/darksafe"}, args...)...)
292		cmd.Dir = ".."
293		var stdout, stderr strings.Builder
294		cmd.Stdout = &stdout
295		cmd.Stderr = &stderr
296		err := cmd.Run()
297		code := 0
298		if err != nil {
299			if exitErr, ok := err.(*exec.ExitError); ok {
300				code = exitErr.ExitCode()
301			} else {
302				t.Fatalf("failed to run command: %v", err)
303			}
304		}
305		return code, stdout.String(), stderr.String()
306	}
307	
308	func TestPlanCLI_DuplicateMemberFailsCleanly(t *testing.T) {
309		dir := t.TempDir()
310		path := filepath.Join(dir, "plan.json")
311		doc := `{
312			"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
313			"batchSize": 2,
314			"clusters": [
315				{"id": "c1", "disabled": true, "disabled": false},
316				{"id": "c2"}
317			]
318		}`
319		if err := os.WriteFile(path, []byte(doc), 0o644); err != nil {
320			t.Fatal(err)
321		}
322		code, stdout, stderr := runCLI(t, "plan", path)
323		if code == 0 {
324			t.Fatalf("expected non-zero exit, got 0; stdout=%q stderr=%q", stdout, stderr)
325		}
326		if stdout != "" {
327			t.Fatalf("expected empty stdout on failure, got %q", stdout)
328		}
329		if !strings.Contains(stderr, "disabled") || !strings.Contains(stderr, "$.clusters[0]") {
330			t.Fatalf("stderr should name field and position, got %q", stderr)
331		}
332	}
333	
334	func TestPlanCLI_ValidFileStillPlans(t *testing.T) {
335		dir := t.TempDir()
336		path := filepath.Join(dir, "plan.json")
337		doc := `{
338			"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
339			"batchSize": 2,
340			"clusters": [{"id": "c2"}, {"id": "c1"}]
341		}`
342		if err := os.WriteFile(path, []byte(doc), 0o644); err != nil {
343			t.Fatal(err)
344		}
345		code, stdout, stderr := runCLI(t, "plan", path)
346		if code != 0 {
347			t.Fatalf("expected exit 0, got %d; stderr=%q", code, stderr)
348		}
349		if !strings.Contains(stdout, `"c1"`) || !strings.Contains(stdout, `"c2"`) {
350			t.Fatalf("expected plan on stdout, got %q", stdout)
351		}
352	}
