// TestParse_DuplicateNamesWithUnicodeEscapes covers every spelling that must
// collapse onto one decoded name: a literal name beside a partially escaped
// one, a name written entirely with escapes, mixed direct/escaped characters,
// and a non-BMP character written directly versus as a surrogate pair. The
// same rule is exercised at each object kind — top-level app info, cluster
// tags, include/exclude conditions, and objects nested under unknown fields,
// including inside arrays where the real index must survive in the path.
func TestParse_DuplicateNamesWithUnicodeEscapes(t *testing.T) {
	base := `"app":"a","revision":"r","image":"i","batchSize":1`
	cases := []struct {
		name      string
		body      string // JSON body without outer braces
		wantField string
		wantPath  string
	}{
		{
			name:      "top-level app literal vs escape",
			body:      `"app":"a","app":"b","revision":"r","image":"i","batchSize":1,"clusters":[]`,
			wantField: "app",
			wantPath:  "$",
		},
		{
			name:      "top-level batchSize fully escaped twice",
			body:      `"app":"a","revision":"r","image":"i","batchSize":1,"batchSize":2,"clusters":[]`,
			wantField: "batchSize",
			wantPath:  "$",
		},
		{
			name:      "cluster id mixed direct and escaped chars",
			body:      base + `,"clusters":[{"id":"x","tags":{}}],"include":[]`,
			wantField: "include",
			wantPath:  "$",
		},
		{
			name:      "tags literal vs partial escape",
			body:      base + `,"clusters":[{"id":"x","tags":{"env":"prod","env":"dev"}}]`,
			wantField: "env",
			wantPath:  "$.clusters[0].tags",
		},
		{
			name:      "tags escaped vs literal order swapped",
			body:      base + `,"clusters":[{"id":"x","tags":{"env":"prod","env":"dev"}}]`,
			wantField: "env",
			wantPath:  "$.clusters[0].tags",
		},
		{
			name:      "tags both fully escaped",
			body:      base + `,"clusters":[{"id":"x","tags":{"env":"prod","env":"dev"}}]`,
			wantField: "env",
			wantPath:  "$.clusters[0].tags",
		},
		{
			name:      "tags non-BMP literal vs surrogate pair",
