		{
			name:      "tags surrogate pair vs literal order swapped",
			body:      base + `,"clusters":[{"id":"x","tags":{"😀":"prod","😀":"dev"}}]`,
			wantField: "😀",
			wantFieldAlt: "",
			wantPath:  "$.clusters[0].tags",
