		})
	}
}

// TestParse_FirstDuplicateInFileOrderWinsWithEscapes checks that escaping does
// not change file-order reporting: among several decoded duplicates the second
// occurrence that appears earliest in the file wins, not the name that sorts
// first, and array indices in the path are the real ones.
func TestParse_FirstDuplicateInFileOrderWinsWithEscapes(t *testing.T) {
	base := `"app":"a","revision":"r","image":"i","batchSize":1`
	// clusters[0] contains a later-in-file duplicate ("zzz"); clusters[1]
	// contains an earlier-in-file duplicate ("env", one spelling escaped).
	// "env" < "zzz" sorts first too, so swap the names to prove ordering is
	// positional: clusters[0] gets "aaa", whose second occurrence appears
	// AFTER clusters[1]'s escaped "env" duplicate in file order.
	doc := `{` + base + `,"clusters":[` +
		`{"id":"a","tags":{"aaa":1,"aaa":2}},` +
		`{"id":"b","tags":{"env":1,"env":2}}]}`
	err := parseDupErr(t, doc)
	msg := err.Error()
	if !strings.Contains(msg, `"env"`) || !strings.Contains(msg, "$.clusters[1].tags") {
		t.Fatalf("expected clusters[1].tags escaped env duplicate (earlier second occurrence), got %q", msg)
	}

	// Conversely the escaped duplicate inside clusters[0].tags must beat a
	// literal duplicate later in clusters[1].
	doc = `{` + base + `,"clusters":[` +
		`{"id":"a","tags":{"env":1,"env":2}},` +
		`{"id":"b","disabled":true,"disabled":false}]}`
	err = parseDupErr(t, doc)
	msg = err.Error()
	if !strings.Contains(msg, `"env"`) || !strings.Contains(msg, "$.clusters[0].tags") {
		t.Fatalf("expected clusters[0].tags escaped env first, got %q", msg)
	}

	// Multiple different-name duplicates inside ONE tags object: the earliest
	// second occurrence wins (here "env" escaped appears before "aaa"'s second
	// occurrence even though "aaa" sorts first).
	doc = `{` + base + `,"clusters":[{"id":"a","tags":{` +
		`"aaa":1,"env":2,"env":3,"aaa":4}}]}`
	err = parseDupErr(t, doc)
	msg = err.Error()
	if !strings.Contains(msg, `"env"`) || !strings.Contains(msg, "$.clusters[0].tags") {
		t.Fatalf("expected earliest second occurrence (escaped env), got %q", msg)
	}
}

// TestParse_EscapedDuplicateBeatsBusinessErrors checks that a decode-equal
// duplicate is caught before any business-field validation, including when
// the app name is missing.
func TestParse_EscapedDuplicateBeatsBusinessErrors(t *testing.T) {
	// Escaped duplicate plus missing app: duplicate error must come first.
	doc := `{"revision":"r","image":"i","batchSize":1,"clusters":[` +
		`{"id":"a","disabled":true,"disabled":false}]}`
	err := parseDupErr(t, doc)
	if !strings.Contains(err.Error(), "disabled") || !strings.Contains(err.Error(), "$.clusters[0]") {
		t.Fatalf("expected escaped duplicate error before missing-app error, got %q", err)
	}

	// Escaped duplicate in tags plus an empty tag key: duplicate wins.
	doc = `{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[` +
		`{"id":"a","tags":{"env":1,"env":2,"":3}}]}`
	err = parseDupErr(t, doc)
	if !strings.Contains(err.Error(), "env") {
		t.Fatalf("expected escaped duplicate before tag-key error, got %q", err)
	}

	// Escaped duplicate at top level while app is also missing.
	doc = `{"revision":"r","revision":"r2","image":"i","batchSize":1,"clusters":[]}`
	err = parseDupErr(t, doc)
	if !strings.Contains(err.Error(), `"revision"`) || !strings.Contains(err.Error(), "$") {
		t.Fatalf("expected top-level escaped duplicate before business error, got %q", err)
	}
}

// TestParse_EscapedNamesThatStayDistinct guards the negative side of the
// decoding rule: comparisons happen on the fully decoded name, with no case
// folding or trimming, and the seen-set is per object — including two clusters
// each holding an "env" tag, even when the spellings differ across objects.
func TestParse_EscapedNamesThatStayDistinct(t *testing.T) {
	base := `"app":"a","revision":"r","image":"i","batchSize":1`
	valid := []string{
		// Case differences survive decoding: E is "E", not "e".
		`{` + base + `,"clusters":[{"id":"x","tags":{"env":"prod","ENV":"dev"}}]}`,
		// Leading space is part of the decoded name ( ), never trimmed.
		`{` + base + `,"clusters":[{"id":"x","tags":{" env":"prod","env":"dev"}}]}`,
		// env vs "env" — same decoded name only within ONE object; the
		// escaped spelling in a different cluster's tags is not a duplicate.
		`{` + base + `,"clusters":[` +
			`{"id":"a","tags":{"env":"prod"}},` +
			`{"id":"b","tags":{"env":"dev"}}]}`,
		// Same decoded name in a parent object and a nested object.
		`{` + base + `,"clusters":[],"meta":{"env":"x","nested":{"env":"y"}}}`,
		// Non-BMP char vs a different non-BMP char: surrogate pairs decode to
		// distinct runes.
		`{` + base + `,"clusters":[{"id":"x","tags":{"😀":"a","😎":"b"}}]}`,
	}
	for i, raw := range valid {
		if _, err := ParseReleaseInput([]byte(raw)); err != nil {
			t.Fatalf("case %d: distinct decoded names must be accepted: %v\n%s", i, err, raw)
		}
	}
}

// TestParse_EscapedAndLiteralSpellingsPlanEqually verifies the usage contract
// for legitimate inputs: writing a name escaped versus literally yields the
// same app info, cluster filtering, batches, and exclusion reasons.
func TestParse_EscapedAndLiteralSpellingsPlanEqually(t *testing.T) {
	literal := `{
		"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
		"batchSize": 2,
		"clusters": [
			{"id": "c3", "tags": {"env": "prod"}},
			{"id": "c1", "tags": {"env": "dev"}},
			{"id": "c2", "disabled": true, "tags": {"env": "prod"}},
			{"id": "c4", "tags": {"env": "prod", "region": "us"}}
		],
		"include": [{"env": "prod"}],
		"exclude": [{"region": "us"}]
	}`
	// Same content with assorted escape spellings in member names (and in one
	// string value): decoding must reconstruct the same document.
	escaped := `{
		"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
		"batchSize": 2,
		"clusters": [
			{"id": "c3", "tags": {"env": "prod"}},
			{"id": "c1", "tags": {"env": "dev"}},
			{"id": "c2", "disabled": true, "tags": {"env": "prod"}},
			{"id": "c4", "tags": {"env": "prod", "region": "us"}}
		],
		"include": [{"env": "prod"}],
		"exclude": [{"region": "us"}]
	}`
	in1, err := ParseReleaseInput([]byte(literal))
	if err != nil {
		t.Fatal(err)
	}
	in2, err := ParseReleaseInput([]byte(escaped))
	if err != nil {
		t.Fatalf("escaped-spelling config must parse: %v", err)
	}
	p1, err := MakeReleasePlan(in1)
	if err != nil {
		t.Fatal(err)
	}
	p2, err := MakeReleasePlan(in2)
	if err != nil {
		t.Fatal(err)
	}
	if fmt.Sprintf("%+v", p1) != fmt.Sprintf("%+v", p2) {
		t.Fatalf("plans differ between spellings:\n literal: %+v\n escaped: %+v", p1, p2)
	}
	if len(p1.Batches) != 1 || strings.Join(p1.Batches[0].Clusters, ",") != "c3" {
		t.Fatalf("unexpected plan: %+v", p1.Batches)
	}
	if len(p1.Excluded) != 3 {
		t.Fatalf("expected 3 excluded, got %+v", p1.Excluded)
	}
}

// TestPlanCLI_DuplicateEscapedMemberFailsCleanly drives the CLI with a file
// whose duplicate only becomes visible after Unicode decoding: it must exit
// non-zero, explain the decoded name and its object position on stderr, and
// write nothing to stdout (no partial plan).
func TestPlanCLI_DuplicateEscapedMemberFailsCleanly(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "plan.json")
	doc := `{
		"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
		"batchSize": 2,
		"clusters": [
			{"id": "c1", "tags": {"env": "prod", "env": "dev"}},
			{"id": "c2"}
		]
	}`
	if err := os.WriteFile(path, []byte(doc), 0o644); err != nil {
		t.Fatal(err)
	}
	code, stdout, stderr := runCLI(t, "plan", path)
	if code == 0 {
		t.Fatalf("expected non-zero exit, got 0; stdout=%q stderr=%q", stdout, stderr)
	}
	if stdout != "" {
		t.Fatalf("expected empty stdout on failure, got %q", stdout)
	}
	if !strings.Contains(stderr, `"env"`) || !strings.Contains(stderr, "$.clusters[0].tags") {
		t.Fatalf("stderr should name decoded field and position, got %q", stderr)
	}
}

// TestPlanCLI_EscapedSpellingsStillPlan checks the CLI accepts a legitimate
// config that uses Unicode escape spellings and outputs the same plan.
func TestPlanCLI_EscapedSpellingsStillPlan(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "plan.json")
	doc := `{
		"app": "payments", "revision": "v1.2.3", "image": "reg/payments:v1.2.3",
		"batchSize": 2,
		"clusters": [{"id": "c2"}, {"id": "c1", "tags": {"env": "dev"}}]
	}`
	if err := os.WriteFile(path, []byte(doc), 0o644); err != nil {
		t.Fatal(err)
	}
	code, stdout, stderr := runCLI(t, "plan", path)
	if code != 0 {
		t.Fatalf("expected exit 0, got %d; stderr=%q", code, stderr)
	}
	if !strings.Contains(stdout, `"c1"`) || !strings.Contains(stdout, `"c2"`) {
		t.Fatalf("expected plan on stdout, got %q", stdout)
	}
}

