// TestPlanCLI_EscapedSpellingsStillPlan checks the CLI accepts a legitimate
// config that uses Unicode escape spellings and outputs the usual plan.
func TestPlanCLI_EscapedSpellingsStillPlan(t *testing.T) {
	dir := t.TempDir()
