func TestParse_DuplicateRejectedRegardlessOfValues(t *testing.T) {
	base := `"app":"a","revision":"r","image":"i","batchSize":1`
	// Same value twice must still be rejected.
	for _, val := range []string{`true`, `false`, `null`, `1`, `1.5`, `"str"`, `[1,2]`, `{"k":"v"}`} {
