mkdir -p /tmp/naivecheck && cat > /tmp/naivecheck/main.go <<'EOF'
package main

import (
	"fmt"
	"regexp"
)

// A naïve pre-validator a regression might introduce: extract raw
// `"key":` spellings inside one object and compare them literally,
// without JSON-unescaping.
var memberRe = regexp.MustCompile(`"(?:\\.|[^"\\])*"\s*:`)

func hasRawDuplicate(obj string) (string, bool) {
	seen := map[string]bool{}
	for _, m := range memberRe.FindAllString(obj, -1) {
		raw := m[:len(m)-1] // drop ':' and surrounding ws
		raw = raw[:len(raw)-0]
		key := raw // keep raw spelling, incl. backslash-u escapes
		for {
			if n := len(key); n > 0 && key[n-1] == ' ' {
				key = key[:n-1]
				continue
			}
			break
		}
		if seen[key] {
			return key, true
		}
		seen[key] = true
	}
	return "", false
}

func main() {
	docs := map[string]string{
		"literal dup":   `{"env":"prod","env":"dev"}`,
		"escaped dup":   "{\"env\":\"prod\",\"\\u0065nv\":\"dev\"}",
		"surrogate dup": "{\"😀\":\"a\",\"\\uD83D\\uDE00\":\"b\"}",
	}
	for name, doc := range docs {
		if k, dup := hasRawDuplicate(doc); dup {
			fmt.Printf("%-15s REJECTED (key %s)\n", name, k)
		} else {
			fmt.Printf("%-15s ACCEPTED  <-- wrongly bypasses the check\n", name)
		}
	}
}
EOF
cd /tmp/naivecheck && go mod init naivecheck >/dev/null 2>&1; go run .

